using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Web.Script.Serialization;
namespace PZ3D {static class UpdateAnnouncementTests {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=2097152};static int checks;static Type service;
 static void Check(bool value,string text){checks++;if(!value)throw new Exception("FAIL "+text);}
 static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
 static object Call(object target,string name){try{return service.GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(target,null);}catch(TargetInvocationException error){throw error.InnerException;}}
 static object New(string data,string version,string notes){return Activator.CreateInstance(service,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{data,version,notes},null);}
 static readonly string notes="# 历史\n## 9.9.9 — 2099-01-01\n- 不属于当前版本\n\n## 1.2.44 — 2026-10-30\n\n- 修复中文 <script> 与 & 字符。\n- 本次第二项。\n\n## 1.2.43 — 2026-10-29\n- 旧内容。\n";
 static void Refuses(Action action,string name){bool refused=false;try{action();}catch{refused=true;}Check(refused,name);}
 static void Native(string root){service=typeof(ModernController).Assembly.GetType("PZ3D.UpdateAnnouncementService",false);Check(service!=null,"installed-version announcement service exists");string data=Path.Combine(root,"preferences"),file=Path.Combine(data,"user-settings","update-announcements.json");var current=New(data,"1.2.44",notes);var first=D(Call(current,"Get"));Check((string)first["version"]=="1.2.44"&&(string)first["date"]=="2026-10-30","exact installed version and release date");Check((bool)first["available"]&&(bool)first["unread"],"fresh ZIP/install is unread");Check(((string)first["body"]).Contains("本次第二项")&&!((string)first["body"]).Contains("不属于当前版本")&&!((string)first["body"]).Contains("旧内容"),"only matching release body is returned");Check(!File.Exists(file),"read does not create preference file");Call(current,"Dismiss");byte[] saved=File.ReadAllBytes(file);var again=D(Call(New(data,"1.2.44",notes),"Get"));Check(!(bool)again["unread"],"same version remains read after new service instance");Call(current,"Dismiss");Check(File.ReadAllBytes(file).SequenceEqual(saved),"repeat dismissal does not rewrite preference");var newer=New(data,"9.9.9",notes);Check((bool)D(Call(newer,"Get"))["unread"],"new installed version is independently unread");Call(newer,"Dismiss");Check(!(bool)D(Call(New(data,"1.2.44",notes),"Get"))["unread"],"rollback does not repeat an already-read version");Check(!(bool)D(Call(New(data,"9.9.9",notes),"Get"))["unread"],"new-version dismissal persists too");
 foreach(string content in new string[]{null,"# no matching section",notes+"\n## 1.2.44 — 2026-10-30\n- duplicate"}){var value=New(Path.Combine(root,"missing"),"1.2.44",content);var view=D(Call(value,"Get"));Check(!(bool)view["available"]&&!string.IsNullOrWhiteSpace((string)view["warning"]),"missing/mismatched/duplicate release has explicit unavailable state");Refuses(()=>Call(value,"Dismiss"),"unavailable notes cannot be silently acknowledged");}
 string corruptData=Path.Combine(root,"corrupt"),corrupt=Path.Combine(corruptData,"user-settings","update-announcements.json");Directory.CreateDirectory(Path.GetDirectoryName(corrupt));File.WriteAllText(corrupt,"owned corrupt preference; preserve");var corruptService=New(corruptData,"1.2.44",notes);var damaged=D(Call(corruptService,"Get"));Check((bool)damaged["available"]&&!string.IsNullOrWhiteSpace((string)damaged["warning"]),"preference failure does not hide built-in notes");Refuses(()=>Call(corruptService,"Dismiss"),"corrupt preference cannot be overwritten");Check(File.ReadAllText(corrupt)=="owned corrupt preference; preserve","corrupt preference bytes preserved");
 foreach(string action in new[]{"updateAnnouncementGet","updateAnnouncementDismiss"}){var payload=action.EndsWith("Dismiss")?new Dictionary<string,object>{{"version",AppVersion.Current}}:new Dictionary<string,object>();var request=Json.Serialize(new{id="ann-test",action=action,payload=payload});ModernHostPolicy.Validate("https://orange.local/index.html",request);Check(ModernHostPolicy.IsNativeRead(action,payload),"announcement uses independent nonbusy host lane: "+action);Refuses(()=>ModernHostPolicy.Validate("https://orange.local/index.html",Json.Serialize(new{id="bad",action=action,payload=new{path="untrusted"}})),"announcement payload cannot choose file path");}
 Refuses(()=>ModernHostPolicy.Validate("https://orange.local/index.html",Json.Serialize(new{id="bad",action="updateAnnouncementDismiss",payload=new{version="0.0.1"}})),"cannot acknowledge a different installed version");
 string game=Path.Combine(root,"game"),user=Path.Combine(root,"user"),nativeData=Path.Combine(root,"native-data");Directory.CreateDirectory(game);Directory.CreateDirectory(user);using(var controller=new ModernController(game,user,nativeData,false)){var view=D(controller.Execute("updateAnnouncementGet",new Dictionary<string,object>()));Check((string)view["version"]==AppVersion.Current&&(bool)view["available"],"production controller reads embedded changelog for executing version");Check(!controller.Busy,"announcement get does not leave global busy");controller.Execute("updateAnnouncementDismiss",new Dictionary<string,object>{{"version",AppVersion.Current}});Check(!(bool)D(controller.Execute("updateAnnouncementGet",new Dictionary<string,object>()))["unread"]&&!controller.Busy,"native dismissal persists without global busy");}
 }
 static int Bridge(string root){Directory.CreateDirectory(root);string game=Path.Combine(root,"game"),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");Directory.CreateDirectory(game);Directory.CreateDirectory(user);using(var controller=new ModernController(game,user,data,false)){Console.WriteLine(Json.Serialize(new{ready=true,version=AppVersion.Current,root=root}));string line;while((line=Console.ReadLine())!=null){Dictionary<string,object> request=null;try{request=ModernHostPolicy.Validate("https://orange.local/index.html",line);string action=(string)request["action"];if(action!="updateAnnouncementGet"&&action!="updateAnnouncementDismiss"&&action!="guideGet"&&action!="guideDismiss")throw new Exception("Fixture accepts announcement and guide actions only");var result=controller.Execute(action,(Dictionary<string,object>)request["payload"]);Console.WriteLine(Json.Serialize(new{id=request["id"],ok=true,data=result}));}catch(Exception error){Console.WriteLine(Json.Serialize(new{id=request==null?"invalid":request["id"],ok=false,error=error.Message}));}}}return 0;}
 public static int Main(string[] args){try{LauncherRuntime.Initialize();Console.InputEncoding=Console.OutputEncoding=new UTF8Encoding(false);if(args[0]=="--bridge")return Bridge(args[1]);Native(args[0]);Console.WriteLine("PASS Update announcement: "+checks+" checks");return 0;}catch(Exception error){Console.WriteLine(error);return 1;}}
}}